const row = $input.first().json;
const messages = {
  unknown_event: 'Event does not exist.',
  event_closed: 'Registration is closed for this event.',
  duplicate_or_invalid: 'Duplicate registration or invalid registration information.'
};
if (row.status === 'registered' && row.ticket) {
  return [{ json: { ok: true, ticket: row.ticket, status: 'registered', httpStatus: 201 } }];
}
return [{ json: { ok: false, status: row.status || 'invalid', message: messages[row.status] || 'Registration was not completed.', httpStatus: row.status === 'duplicate_or_invalid' ? 409 : row.status === 'unknown_event' ? 404 : 400 } }];
